// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    bytes32 constant IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    function setUp() public { c = new VaultAdapter(); }

    function testFuzz_property(bytes32 noise, address caller) public {
        // The deciding value is public: proxiableUUID() must equal the ERC-1967
        // implementation slot no matter who calls it or what external input is supplied.
        vm.prank(caller);
        bytes32 returned = c.proxiableUUID();
        assertTrue(returned == IMPLEMENTATION_SLOT && returned != bytes32(0));
    }
}
